/**
 * Scheduled US economic news, per bar.
 *
 * The calendar (`newsCalendar.js`) is generated by `functions/ml/econ_calendar.py`
 * from the publishers' own schedules (BLS, BEA, Census, the Fed, ALFRED release
 * vintages), so the Python studies and this engine read the same events. Impact
 * tiers mirror ForexFactory's folders — high = red, medium = orange, low =
 * yellow — but they are our assignment, not FF's historical labels.
 *
 * Knowing that a release is scheduled is not look-ahead: the schedules are
 * published months in advance. What a bar may not know is the number, and
 * nothing here carries it.
 *
 * Coverage: every event type is complete only up to its `coverEnd`. Bars past
 * the coverage of the selected types get NaN ("unknown"), never 0, so a run on
 * fresh data cannot silently read as "no news".
 */

import { EVENTS, EVENT_TYPES, RETRIEVED } from './newsCalendar'

export { EVENT_TYPES, RETRIEVED }

export const IMPACT_RANK = { low: 1, medium: 2, high: 3 }

export const IMPACT_OPTIONS = [
  { id: 'high', label: 'High (red)' },
  { id: 'medium', label: 'Medium+ (orange)' },
  { id: 'low', label: 'Any (yellow+)' },
]

const NA = Number.NaN
const INTERVAL_SECONDS = { '1m': 60, '5m': 300, '15m': 900, '30m': 1800, '1h': 3600, '4h': 14400, '1d': 86400 }

function selectedTypes(minImpact = 'high', types = null) {
  const rank = IMPACT_RANK[minImpact] ?? IMPACT_RANK.high
  return Object.keys(EVENT_TYPES).filter((k) => IMPACT_RANK[EVENT_TYPES[k].impact] >= rank && (!types || types.includes(k)))
}

/** Events at or above `minImpact`: `{ t, type, label, impact, source }`, oldest first.
 *  `sources` keeps only some provenance classes (official | vintage | rule | derived). */
export function newsEvents({ minImpact = 'high', types = null, sources = null } = {}) {
  const keep = new Set(selectedTypes(minImpact, types))
  const out = []
  for (const [t, type, source] of EVENTS) {
    if (!keep.has(type) || (sources && !sources.includes(source))) continue
    const meta = EVENT_TYPES[type]
    out.push({ t, type, label: meta.label, impact: meta.impact, source })
  }
  return out
}

/** Epoch seconds from which the selected types are no longer known complete. */
export function newsCoverEnd({ minImpact = 'high', types = null } = {}) {
  let end = Infinity
  for (const k of selectedTypes(minImpact, types)) end = Math.min(end, EVENT_TYPES[k].coverEnd)
  return end
}

/** Bar length in seconds: the interval label, else the median spacing. */
export function barSeconds(ds) {
  const known = INTERVAL_SECONDS[ds.interval]
  if (known) return known
  const n = Math.min(ds.time.length, 200)
  const gaps = []
  for (let i = 1; i < n; i++) gaps.push(ds.time[i] - ds.time[i - 1])
  gaps.sort((a, b) => a - b)
  return gaps.length ? gaps[gaps.length >> 1] : 300
}

const eventTimes = (opts) => Float64Array.from(newsEvents(opts), (e) => e.t)

/** First index with arr[j] > x (arr sorted ascending). */
function upperBound(arr, x) {
  let lo = 0
  let hi = arr.length
  while (lo < hi) {
    const mid = (lo + hi) >> 1
    if (arr[mid] <= x) lo = mid + 1
    else hi = mid
  }
  return lo
}

/**
 * 1 where bar i's span [time, time + bar) overlaps an event window
 * [event − beforeMin, event + afterMin), 0 where it does not, NaN past coverage.
 * `beforeMin = afterMin = 0` marks the bar the release prints in.
 */
export function newsWindowFlags(ds, { minImpact = 'high', beforeMin = 5, afterMin = 15, types = null, sources = null } = {}) {
  const n = ds.time.length
  const out = new Float64Array(n)
  const ev = eventTimes({ minImpact, types, sources })
  const bar = barSeconds(ds)
  const before = beforeMin * 60
  // A release is an instant; give it one second so a 0/0 window still marks
  // the bar it prints in.
  const after = Math.max(afterMin * 60, 1)
  const coverEnd = newsCoverEnd({ minImpact, types })
  for (let i = 0; i < n; i++) {
    const t = ds.time[i]
    if (t >= coverEnd) {
      out[i] = NA
      continue
    }
    // Windows share one width, so the first whose end is past the bar start is
    // the only candidate; it overlaps if it also starts before the bar ends.
    const j = upperBound(ev, t - after)
    out[i] = j < ev.length && ev[j] - before < t + bar ? 1 : 0
  }
  return out
}

/** Minutes from each bar's close to the next selected event after it. */
export function minutesToNextNews(ds, { minImpact = 'high', types = null, sources = null } = {}) {
  const n = ds.time.length
  const out = new Float64Array(n).fill(NA)
  const ev = eventTimes({ minImpact, types, sources })
  const bar = barSeconds(ds)
  const coverEnd = newsCoverEnd({ minImpact, types })
  for (let i = 0; i < n; i++) {
    const at = ds.time[i] + bar
    if (at >= coverEnd) continue
    const j = upperBound(ev, at)
    if (j < ev.length) out[i] = (ev[j] - at) / 60
  }
  return out
}

/** Minutes since the latest selected event at or before each bar's close. */
export function minutesSinceNews(ds, { minImpact = 'high', types = null, sources = null } = {}) {
  const n = ds.time.length
  const out = new Float64Array(n).fill(NA)
  const ev = eventTimes({ minImpact, types, sources })
  const bar = barSeconds(ds)
  const coverEnd = newsCoverEnd({ minImpact, types })
  for (let i = 0; i < n; i++) {
    const at = ds.time[i] + bar
    if (at >= coverEnd) continue
    const j = upperBound(ev, at) - 1
    if (j >= 0) out[i] = (at - ev[j]) / 60
  }
  return out
}

/**
 * Engine flags for a news blackout. `blocked[i]` — the next bar overlaps a
 * window, so an order placed at bar i's close (filled at the next open) would
 * be held through news: the target is forced flat. `end[i]` — the first such
 * bar, where an open position is closed at the close. A strategy may re-enter
 * at the open of the first bar after the window. `uncovered` counts bars the
 * calendar cannot speak for; they are left unblocked.
 */
export function newsBlackoutFlags(ds, { impact = 'high', beforeMin = 5, afterMin = 15, types = null, sources = null } = {}) {
  const flags = newsWindowFlags(ds, { minImpact: impact, beforeMin, afterMin, types, sources })
  const n = flags.length
  const blocked = new Uint8Array(n)
  const end = new Uint8Array(n)
  let uncovered = 0
  for (let i = 0; i < n; i++) {
    if (Number.isNaN(flags[i])) uncovered++
    if (i + 1 < n && flags[i + 1] === 1) {
      blocked[i] = 1
      if (flags[i] !== 1) end[i] = 1
    }
  }
  return { end, blocked, uncovered }
}
